# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HİCRETİN SEBEPLERİ VE DARÜ\'N-NEDVE SUİKAST KARARI (622)</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hicrete Zemin Hazırlayan Sebepler</text>\n  <text x="50" y="105" font-size="11.5" fill="#334155">• Mekkeli müşriklerin artan baskı ve işkenceleri</text>\n  <text x="50" y="130" font-size="11.5" fill="#334155">• Müslümanların dinlerini özgürce yaşayamaması</text>\n  <text x="50" y="155" font-size="11.5" fill="#334155">• Ebû Talip ve Hz. Hatice\'nin vefatı (Hüzün Yılı)</text>\n  <text x="50" y="180" font-size="11.5" fill="#334155">• I. ve II. Akabe Biatları ile Medineli</text>\n  <text x="62" y="198" font-size="11" fill="#475569">Müslümanların (Ensar) Peygamberimizi daveti</text>\n  <text x="185" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">İlahi İzin: 622 yılında Medine\'ye göç</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Darü\'n-Nedve Kararı ve İlahi Uyarı</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">• Müşrikler Darü\'n-Nedve\'de toplandı.</text>\n  <text x="380" y="130" font-size="11.5" fill="#334155">• Ebû Cehil\'in teklifi: Her kabileden birer</text>\n  <text x="392" y="148" font-size="11" fill="#475569">genç seçilerek ortak suikast düzenlenmesi.</text>\n  <text x="380" y="175" font-size="11.5" fill="#334155">• Cebrail (a.s.) tuzağı haber verdi ve</text>\n  <text x="392" y="193" font-size="11" fill="#475569">hicret iznini bildirdi (Enfâl Suresi, 30. ayet).</text>\n  <text x="515" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">&quot;Allah tuzak kuranların en hayırlısıdır.&quot;</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HİCRET PLANI: EMANET BİLİNCİ, TEDBİR VE GÖREV PAYLAŞIMI</text>\n  <rect x="30" y="50" width="200" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="130" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Hz. Ali\'nin Fedakarlığı</text>\n  <text x="45" y="105" font-size="11.5" fill="#334155">• Peygamberimizin yatağına</text>\n  <text x="55" y="123" font-size="11" fill="#475569">yatarak müşrikleri yanılttı.</text>\n  <text x="45" y="150" font-size="11.5" fill="#334155">• Peygamberimizdeki emanetleri</text>\n  <text x="55" y="168" font-size="11" fill="#475569">sahiplerine teslim etti.</text>\n  <text x="130" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Cesaret, Sadakat ve Emanet</text>\n  <rect x="250" y="50" width="200" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hz. Ebû Bekir ve Ailesi</text>\n  <text x="265" y="105" font-size="11.5" fill="#334155">• Yol arkadaşı: Hz. Ebû Bekir</text>\n  <text x="265" y="130" font-size="11.5" fill="#334155">• Abdullah: Mekke\'den haber</text>\n  <text x="265" y="155" font-size="11.5" fill="#334155">• Hz. Esma: Erzak taşıdı</text>\n  <text x="265" y="180" font-size="11.5" fill="#334155">• Âmir b. Füheyre: Koyun</text>\n  <text x="275" y="198" font-size="11" fill="#475569">sürüsüyle ayak izlerini sildi.</text>\n  <rect x="470" y="50" width="200" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Stratejik Tedbirler</text>\n  <text x="485" y="105" font-size="11.5" fill="#334155">• Kuzeydeki Medine yerine</text>\n  <text x="495" y="123" font-size="11" fill="#475569">güneydeki Sevr Mağarası\'na</text>\n  <text x="495" y="140" font-size="11" fill="#475569">gidilerek 3 gece gizlenildi.</text>\n  <text x="485" y="168" font-size="11.5" fill="#334155">• Uzman rehber Abdullah bin</text>\n  <text x="495" y="186" font-size="11" fill="#475569">Uraykıt ile sahil yolu seçildi.</text>\n  <text x="570" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Önce Tedbir, Sonra Tevekkül!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SEVR MAĞARASI VE HİCRET YOLCULUĞUNDAN KUBA\'YA VARIŞ</text>\n  <rect x="40" y="55" width="295" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sevr Mağarası ve Tevekkül (Tevbe, 40)</text>\n  <text x="55" y="110" font-size="11.5" fill="#334155">• Mağara ağzında örümcek ağı ve güvercin</text>\n  <text x="68" y="128" font-size="11" fill="#475569">yuvası ile Allah\'ın (c.c.) yardımı tecelli etti.</text>\n  <text x="55" y="155" font-size="11.5" fill="#334155">• Endişelenen Hz. Ebû Bekir\'e Peygamberimiz:</text>\n  <text x="187" y="185" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">&quot;Üzülme! Şüphesiz Allah bizimle beraberdir.&quot;</text>\n  <text x="187" y="210" text-anchor="middle" font-size="11" fill="#475569">(Lâ tahzen innallâhe meanâ - Tevbe, 40)</text>\n  <rect x="365" y="55" width="295" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Sürâka Olayı ve Kuba\'ya Varış</text>\n  <text x="380" y="110" font-size="11.5" fill="#334155">• Ödül için peşlerine düşen Sürâka bin Mâlik\'in</text>\n  <text x="392" y="128" font-size="11" fill="#475569">atının ayakları kuma saplandı, eman diledi.</text>\n  <text x="380" y="155" font-size="11.5" fill="#334155">• Kuba\'da İslam\'ın ilk mescidi (Kuba Mescidi)</text>\n  <text x="392" y="173" font-size="11" fill="#475569">inşa edildi; Ranuna Vadisi\'nde ilk Cuma</text>\n  <text x="392" y="191" font-size="11" fill="#475569">namazı kılınarak Medine\'ye ulaşıldı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
